 * the original text on ONE line, otherwise verbatim. Read it; do not run it —
 * the first `--` comment would comment out everything after it. For a runnable
 * copy use SSMS Tasks > Generate Scripts.
 *
 * Not one of the 18 audited objects: called by C# after every jsApproveBudget
 * to find who to notify (UserService.GetUserIdsSendNotificatiosAsync).
 */
CREATE PROCEDURE [bud].[jsBudgetNotify]      @budgetId int = 104     AS  BEGIN  SELECT DISTINCT      jde.id AS budgetId,      jde.docEntry,      jde.status,      jde.currentStageId,      js.id AS stageId,      js.stage AS stageName,      js.approvalId,      js.createdBy,      js.createdOn,      js.company,      js.rejectid,      js.description,      jst.templateId AS currentTemplateId,      jst.priority AS currentStagePriority,      next_stage.id AS nextStageId,      next_stage.stage AS nextStageName,      jded.docId,      -- Count current approvals for the stage      (          SELECT COUNT(*)          FROM bud.jsBudgetStatusWorkflow bsw          WHERE bsw.stageId = jde.currentStageId          AND bsw.docId = jde.id      ) AS currentApprovalCount,      -- Get the required approvals for the current stage      js.approvalId AS requiredApprovals,      -- Determine which users to show based on approval logic      CASE           -- If current approvals are less than required, show remaining users in current stage          WHEN (              SELECT COUNT(*)              FROM bud.jsBudgetStatusWorkflow bsw              WHERE bsw.stageId = jde.currentStageId              AND bsw.docId = jde.id          ) < js.approvalId           THEN (              SELECT STRING_AGG(CONCAT(next_u.firstName, ' ', next_u.lastName), ', ') AS users              FROM dbo.jsUserStage next_us              INNER JOIN jsUser next_u ON next_u.userId = next_us.userId              LEFT JOIN bud.jsBudgetStatusWorkflow next_bsw                   ON next_bsw.userId = next_us.userId                   AND next_bsw.stageId = jde.currentStageId                  AND next_bsw.docId = jde.id              WHERE next_us.stageId = jde.currentStageId              AND next_bsw.docId IS NULL  -- Only include users who haven't approved yet          )          -- If all required approvals are received, show next stage users          ELSE (              SELECT STRING_AGG(CONCAT(next_stage_u.firstName, ' ', next_stage_u.lastName), ', ')               FROM jsStageTemplate next_jst              JOIN jsStage next_js ON next_jst.stageId = next_js.id              JOIN jsUserStage next_stage_us ON next_js.id = next_stage_us.stageId              JOIN jsUser next_stage_u ON next_stage_us.userId = next_stage_u.userId              WHERE next_jst.templateId = jst.templateId              AND next_jst.priority = jst.priority + 1          )      END AS usersToApprove,            -- Also include the actual user IDs (not just names) for programmatic use      CASE           -- If current approvals are less than required, show remaining user IDs from current stage          WHEN (              SELECT COUNT(*)              FROM bud.jsBudgetStatusWorkflow bsw              WHERE bsw.stageId = jde.currentStageId              AND bsw.docId = jde.id          ) < js.approvalId           THEN (              SELECT STRING_AGG(CAST(next_us.userId AS VARCHAR(50)), ',')               FROM dbo.jsUserStage next_us              LEFT JOIN bud.jsBudgetStatusWorkflow next_bsw                   ON next_bsw.userId = next_us.userId                   AND next_bsw.stageId = jde.currentStageId                  AND next_bsw.docId = jde.id              WHERE next_us.stageId = jde.currentStageId              AND next_bsw.docId IS NULL  -- Only include users who haven't approved yet          )          -- If all required approvals are received, show next stage user IDs          ELSE (              SELECT STRING_AGG(CAST(next_stage_us.userId AS VARCHAR(50)), ',')               FROM jsStageTemplate next_jst              JOIN jsStage next_js ON next_jst.stageId = next_js.id              JOIN jsUserStage next_stage_us ON next_js.id = next_stage_us.stageId              WHERE next_jst.templateId = jst.templateId              AND next_jst.priority = jst.priority + 1          )      END AS userIdsToApprove,      -- Keep original fields for reference      (          SELECT STRING_AGG(CONCAT(next_u.firstName, ' ', next_u.lastName), ', ')           FROM dbo.jsUserStage next_us          INNER JOIN jsUser next_u ON next_u.userId = next_us.userId          LEFT JOIN bud.jsBudgetStatusWorkflow next_bsw               ON next_bsw.userId = next_us.userId               AND next_bsw.stageId = jde.currentStageId              AND next_bsw.docId = jde.id          WHERE next_us.stageId = jde.currentStageId          AND next_bsw.docId IS NULL      ) AS currentStageApprovers,      (          SELECT STRING_AGG(CONCAT(next_stage_u.firstName, ' ', next_stage_u.lastName), ', ')           FROM jsStageTemplate next_jst          JOIN jsStage next_js ON next_jst.stageId = next_js.id          JOIN jsUserStage next_stage_us ON next_js.id = next_stage_us.stageId          JOIN jsUser next_stage_u ON next_stage_us.userId = next_stage_u.userId          WHERE next_jst.templateId = jst.templateId          AND next_jst.priority = jst.priority + 1      ) AS nextStageUsers,      b.BUDGET,      b.SUB_BUDGET  FROM       bud.jsDocEntry jde   JOIN       jsUserStage jus ON jde.currentStageId = jus.stageId  JOIN       jsUser ju ON jus.userId = ju.userId  JOIN      jsStage js ON jde.currentStageId = js.id  JOIN      jsStageTemplate jst ON js.id = jst.stageId  JOIN      bud.jsDocEnrtyDetail jded ON jde.id = jded.docId  JOIN      BUD.jsBudgetTable b ON jde.docEntry = b.DocEntry  LEFT JOIN      jsStageTemplate next_template ON jst.templateId = next_template.templateId                                    AND next_template.priority = jst.priority + 1  LEFT JOIN      jsStage next_stage ON next_template.stageId = next_stage.id  WHERE       jde.id = @budgetId;  END
